const {chromium}=require('playwright'); const fs=require('fs'); const path=require('path');
const F='file:///tmp/vid/node_modules/@fontsource/';
const LOGO=`<svg width="64" height="64" viewBox="0 0 64 64"><path d="M12 10H52V36L32 55L12 36Z" fill="#2450D6" stroke="#2450D6" stroke-width="6" stroke-linejoin="round"/><circle cx="32" cy="30" r="12.5" fill="#fff"/><path d="M25.2 23.2Q29 30 25.2 36.8" stroke="#2450D6" stroke-width="2.2" fill="none" stroke-linecap="round"/><path d="M38.8 23.2Q35 30 38.8 36.8" stroke="#2450D6" stroke-width="2.2" fill="none" stroke-linecap="round"/></svg>`;
const CSS=`@font-face{font-family:B;font-weight:800;src:url(data:font/woff2;base64,)}
@font-face{font-family:D;font-weight:500;src:url(data:font/woff2;base64,)}
@font-face{font-family:D;font-weight:700;src:url(data:font/woff2;base64,)}
*{box-sizing:border-box}body{margin:0;width:1080px;height:1920px;background:#F6F7F9;color:#14161B;font-family:D;overflow:hidden}
.wrap{position:absolute;left:80px;right:150px;top:200px;bottom:430px;display:flex;flex-direction:column;justify-content:center}.brand{position:absolute;top:-80px;left:0}
.brand{display:flex;align-items:center;gap:16px;font:800 46px B;letter-spacing:-1px}
.hook{font:800 92px/1.0 B;letter-spacing:-2.5px;margin:70px 0 22px}
.sub{font:500 44px D;color:#3A3F4B;margin:0 0 56px}
.label{font:700 30px D;color:#6B7280;letter-spacing:2px;text-transform:uppercase;margin-bottom:22px}
.row{border:4px solid transparent;display:flex;align-items:center;gap:26px;background:#fff;border-radius:28px;padding:30px 34px;margin-bottom:20px;box-shadow:0 4px 18px rgba(20,22,27,.07);min-height:136px}
.rank{flex:none;width:72px;height:72px;border-radius:20px;background:#EEF1F6;color:#6B7280;font:800 40px B;display:flex;align-items:center;justify-content:center}
.name{flex:1;font:700 44px D;line-height:1.1}.name small{display:block;font:500 30px D;color:#6B7280;margin-top:4px}
.val{font:800 48px B;color:#2450D6;white-space:nowrap}
.row.win{background:#2450D6;color:#fff}.row.win .rank{background:#fff;color:#2450D6}.row.win .val{color:#fff}.row.win small{color:#C9D5FF}
.row.empty{background:transparent;box-shadow:none;border:4px dashed #D5DAE3}.row.empty .name{color:#B4BAC6}
.clue{font-size:120px;color:#2450D6;margin-top:20px}.count{font:800 360px/1 B;color:#2450D6;text-align:center;margin-top:40px}
.cta{font:800 64px/1.05 B;letter-spacing:-1.5px;margin-top:70px}.url{align-self:flex-start;display:inline-block;margin-top:30px;background:#2450D6;color:#fff;font:800 64px B;padding:22px 40px;border-radius:26px}
.fact{font:700 54px/1.2 D;margin-top:60px}.src{font:500 30px D;color:#6B7280;margin-top:22px}`;
const row=(r,it,cls='')=>`<div class="row ${cls}"><div class="rank">${r}</div><div class="name">${it?it[0]:'?'}${it&&it[1]?`<small>${it[1]}</small>`:''}</div>${it&&it[2]?`<div class="val">${it[2]}</div>`:''}</div>`;
const head=`<div class="brand">${LOGO}Ballpark</div>`;
function states(v){
  const S=[]; const scr=v.scr.map(i=>[v.items[i][0],v.items[i][1],null]);
  const listUnranked=scr.map(it=>row('•',it)).join('');
  if(v.clue){
    S.push([4.0,`${head}<div class="label">Hidden stat · your only clue</div><div class="hook clue">“${v.clue}”</div><div class="sub">${v.hook}</div>${listUnranked}`]);
    for(const n of [3,2,1]) S.push([1,`${head}<div class="hook">What's the stat?</div><div class="sub">Comment your guess + your order</div><div class="count">${n}</div>`]);
    S.push([1.6,`${head}<div class="label">The hidden stat was</div><div class="hook">${v.stat}</div><div class="sub">Clue: “${v.clue}”</div>`]);
  } else {
  S.push([3.5,`${head}<div class="hook">${v.hook}</div><div class="sub">${v.sub}</div><div class="label">Most at top → least at bottom</div>${listUnranked}`]);
  for(const n of [3,2,1]) S.push([1,`${head}<div class="hook">Comment your order</div><div class="sub">${v.stat}</div><div class="count">${n}</div>`]);
  }
  for(let k=5;k>=1;k--){ let h=''; for(let r=1;r<=5;r++){ h+= r>=k? row(r,v.items[r-1], r===1?'win':'') : row(r,null,'empty'); }
    S.push([k===1?2.2:1.4,`${head}<div class="hook" style="font-size:80px">The answer</div><div class="sub">${v.stat}</div>${h}`]); }
  S.push([4.2,`${head}<div class="fact">${v.fact}</div><div class="src">Source: ${v.src}</div><div class="cta">New puzzle every day.</div><div class="url">playballpark.xyz</div>`]);
  return S;
}
const V=JSON.parse(fs.readFileSync(process.argv[2]||'/tmp/vid/videos.json'));
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1080,height:1920}});
for(const v of V){const dir=`/tmp/vid/frames/${v.id}`;fs.mkdirSync(dir,{recursive:true});const st=states(v);let list='';
 for(let i=0;i<st.length;i++){await p.setContent(`<style>${CSS}</style><div class="wrap">${st[i][1]}</div>`);await p.evaluate(()=>document.fonts.ready);
  const f=`${dir}/${String(i).padStart(2,'0')}.png`;await p.screenshot({path:f});list+=`file '${f}'\nduration ${st[i][0]}\n`;}
 list+=`file '${dir}/${String(st.length-1).padStart(2,'0')}.png'\n`; fs.writeFileSync(`${dir}/list.txt`,list);}
await b.close();})();
